/**
 * Package Router Payload Normalizer — n8n Code Node
 *
 * Normalizes both folder_watcher and ingest_sorter webhook payloads
 * into a common format before the Package Router Switch node routes
 * them to the appropriate sub-workflow.
 *
 * Input: items[0].json from either folder_watcher or ingest_sorter webhook
 * Output: Normalized payload with consistent keys for routing
 *
 * Paste this into an n8n Code node in the Package Router workflow,
 * positioned between the webhook trigger and the Switch node.
 */

const input = items[0].json;

// Detect source based on payload shape
const hasIngestSorterFields = input.mission_id && !input.folder_name;
const hasFolderWatcherFields = input.folder_name && !input.mission_id;

let normalized;

if (hasIngestSorterFields) {
  // --- ingest_sorter payload: pass through with metadata ---
  normalized = {
    mission_id: input.mission_id,
    mission_number: input.mission_number,
    package_type: input.package_type,
    photo_count: input.photo_count || 0,
    video_count: input.video_count || 0,
    has_ppk_data: input.has_ppk_data || false,
    source: "ingest_sorter",
    needs_mission_lookup: false,
    is_fallback: false,
    folder_path: input.sorted_folder || input.folder_path || "",
  };
} else if (hasFolderWatcherFields) {
  // --- folder_watcher payload: parse folder name for package_type ---
  const folderName = input.folder_name;
  const regex = /^SAI_M(\d{4})_(.+?)_(\d{8})$/;
  const match = folderName.match(regex);

  let missionNumber = input.mission_number || 0;
  let packageType = "unknown";

  if (match) {
    missionNumber = parseInt(match[1], 10);
    packageType = match[2];
  }

  normalized = {
    mission_id: null,
    mission_number: missionNumber,
    package_type: packageType,
    photo_count: input.photo_count || 0,
    video_count: input.video_count || 0,
    has_ppk_data: input.has_ppk_data || false,
    source: "folder_watcher",
    needs_mission_lookup: true,
    is_fallback: true,
    folder_path: input.folder_path || "",
  };
} else {
  // --- Unknown payload shape: pass through with unknown markers ---
  normalized = {
    mission_id: input.mission_id || null,
    mission_number: input.mission_number || 0,
    package_type: input.package_type || "unknown",
    photo_count: input.photo_count || 0,
    video_count: input.video_count || 0,
    has_ppk_data: input.has_ppk_data || false,
    source: "unknown",
    needs_mission_lookup: !input.mission_id,
    is_fallback: false,
    folder_path: input.folder_path || "",
  };
}

return [{ json: normalized }];

const lookup = items[0].json;
const prev = $('Normalize Payload').first().json;
const mission = Array.isArray(lookup) ? lookup[0] : lookup;
return [{json: {
  ...prev,
  mission_id: mission?.id || prev.mission_id,
  address: mission?.address || '',
  city: mission?.city || '',
  needs_mission_lookup: false
}}];

const lookup = items[0].json;
const prev = $('Normalize Payload').first().json;
const mission = Array.isArray(lookup) ? lookup[0] : lookup;
return [{json: {
  ...prev,
  address: mission?.address || '',
  city: mission?.city || ''
}}];

// Build processing steps and prepare job creation payload
const templateData = items[0].json;
const prev = $('Check Duplicate Job').first().json;
// Recover the normalized payload from before the duplicate check
// The duplicate check HTTP node returns the Supabase response, so we
// need to get the normalized payload from an earlier node.
// After merge nodes, the payload flows through Check Duplicate Job.
// We reference Normalize Payload and merge nodes for original data.
const normalizedBase = $('Normalize Payload').first().json;

// Try to get merged address/city from whichever merge node ran
let address = '';
let city = '';
let missionId = normalizedBase.mission_id;
try {
  const merged = $('Merge Mission ID').first().json;
  address = merged.address || '';
  city = merged.city || '';
  missionId = merged.mission_id || missionId;
} catch (e) {
  try {
    const merged = $('Merge Address').first().json;
    address = merged.address || '';
    city = merged.city || '';
  } catch (e2) {
    // No merge data available
  }
}

const packageType = normalizedBase.package_type;

// Step mapping — source of truth from test_package_router_integration.py
const STEP_MAP = {
  re_standard: [
    {name: 'color_grade', status: 'pending'},
    {name: 'delivery_packaging', status: 'pending'}
  ],
  real_estate: [
    {name: 'color_grade', status: 'pending'},
    {name: 'delivery_packaging', status: 'pending'}
  ],
  mapping: [
    {name: 'mipmap_launch', status: 'pending'},
    {name: 'ortho_harvest', status: 'pending'},
    {name: 'delivery_packaging', status: 'pending'}
  ],
  site_survey: [
    {name: 'mipmap_launch', status: 'pending'},
    {name: 'ortho_harvest', status: 'pending'},
    {name: 'delivery_packaging', status: 'pending'}
  ],
  environmental_survey: [
    {name: 'mipmap_launch', status: 'pending'},
    {name: 'ortho_harvest', status: 'pending'},
    {name: 'delivery_packaging', status: 'pending'}
  ],
  video: [
    {name: 'v1_color', status: 'pending'},
    {name: 'v1_5_metadata', status: 'pending'},
    {name: 'v2_srt', status: 'pending'},
    {name: 'v3_qa', status: 'pending'},
    {name: 'v4_proxy', status: 'pending'},
    {name: 'v5_resolve_gate', status: 'pending'},
    {name: 'v6_export', status: 'pending'},
    {name: 'delivery_packaging', status: 'pending'}
  ],
  construction_hybrid: [],
  adiat: []
};

const steps = STEP_MAP[packageType] || [];  // Unknown -> empty (manual)
const status = steps.length > 0 ? 'queued' : 'manual';

// Parse template config (Supabase returns array)
const template = Array.isArray(templateData) ? templateData[0] : templateData;
const templateConfig = template?.config || template?.vegetation_config || {};

return [{json: {
  // Fields for INSERT into processing_jobs
  mission_id: missionId,
  package_type: packageType,
  status: status,
  steps: steps,
  source: normalizedBase.source,
  template_config: templateConfig,
  // Pass-through fields for downstream sub-workflows
  folder_path: normalizedBase.folder_path,
  mission_number: normalizedBase.mission_number,
  source_platform: normalizedBase.source,
  address: address,
  city: city
}}];

// Merge processing_job_id from INSERT response into payload for sub-workflows
const created = items[0].json;
const jobRow = Array.isArray(created) ? created[0] : created;
const prev = $('Build Steps and Create Job').first().json;

return [{json: {
  mission_id: prev.mission_id,
  package_type: prev.package_type,
  mission_number: prev.mission_number,
  folder_path: prev.folder_path,
  processing_job_id: jobRow?.id || null,
  source_platform: prev.source_platform,
  address: prev.address,
  city: prev.city
}}];
